import{_ as d,o as a,c as r,aO as e}from"./chunks/framework.BFrk9dwu.js";const c=JSON.parse('{"title":"AI教程","description":"","frontmatter":{"title":"AI教程","date":"2026-11-27T17:40:00.000Z","sidebarSort":1,"categories":["ai"],"permalink":"/pages/3bb977"},"headers":[],"relativePath":"ai/index.md","filePath":"ai/index.md"}'),o={name:"ai/index.md"};function h(n,t,i,l,s,b){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="ai教程" tabindex="-1">AI教程 <a class="header-anchor" href="#ai教程" aria-label="Permalink to &quot;AI教程&quot;">​</a></h1><h2 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to &quot;概念&quot;">​</a></h2><p>AI 教程这一栏，讲的不是「人工智能」这个大词，而是能被你直接用在项目和工作里的几件事：<strong>把模型理解成一个只会续写文字的黑盒，然后学会怎么喂它、怎么接它、怎么验证它。</strong></p><p>四个先记住的名词：</p><table tabindex="0"><thead><tr><th>名词</th><th>一句话</th></tr></thead><tbody><tr><td>大模型（LLM）</td><td>只做一件事：根据前文预测下一个 token。对话、写代码、翻译都是这件事的副产品</td></tr><tr><td>提示词（prompt）</td><td>你给的输入，包含角色、任务、约束、示例四类信息</td></tr><tr><td>上下文窗口</td><td>一次请求模型能同时看到多少 token，超了就截断</td></tr><tr><td>token</td><td>模型处理文本的最小单位，中文大致一字一个，英文一个词约 1.3 个</td></tr></tbody></table><p>把它当成一个<strong>记性很好、但完全不了解你处境的实习生</strong>：交代得越具体，产出越可用；留白越多，它越会自己编。</p><h3 id="它到底在算什么" tabindex="-1">它到底在算什么 <a class="header-anchor" href="#它到底在算什么" aria-label="Permalink to &quot;它到底在算什么&quot;">​</a></h3><p>只有两段过程，别混着理解：</p><ul><li><strong>训练</strong>：拿海量文本做「下一个词」的预测，反复调参数，把语言规律压进权重。这一步不发生在你机器上</li><li><strong>推理</strong>：加载权重，输入 token 序列，输出下一个 token 的概率分布，采样一个拼回输入，继续预测。<strong>逐 token 生成，所以耗时和费用都跟着输出长度走</strong></li></ul><p>这也解释了它为什么不会「查资料」：推理时它只看得到你给的那段上下文，权重里只有训练时的模糊记忆。</p><h3 id="上下文窗口决定能记多少" tabindex="-1">上下文窗口决定能记多少 <a class="header-anchor" href="#上下文窗口决定能记多少" aria-label="Permalink to &quot;上下文窗口决定能记多少&quot;">​</a></h3><table tabindex="0"><thead><tr><th>窗口量级</th><th>大约相当于</th><th>说明</th></tr></thead><tbody><tr><td>4K</td><td>三千字中文</td><td>老模型常态，够一次问答</td></tr><tr><td>8K–32K</td><td>六千到两万字</td><td>单篇长文、一个中等代码文件</td></tr><tr><td>128K 以上</td><td>十万字级别</td><td>能塞整本手册，但中间内容容易被忽略</td></tr></tbody></table><p>窗口大不等于记得牢。把关键要求在<strong>开头和结尾各说一遍</strong>，比只写在中间可靠得多。</p><h3 id="温度和采样参数" tabindex="-1">温度和采样参数 <a class="header-anchor" href="#温度和采样参数" aria-label="Permalink to &quot;温度和采样参数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>作用</th><th>常用取值</th></tr></thead><tbody><tr><td>temperature</td><td>越高越随机，越低越保守</td><td>事实问答 0–0.3；创意 0.7–1.0</td></tr><tr><td>top_p</td><td>只在概率累计到 p 的词里采样</td><td>保持默认，与温度二选一调</td></tr><tr><td>max_tokens</td><td>限制输出长度</td><td>按场景给上限，防止话痨</td></tr><tr><td>frequency_penalty</td><td>抑制重复用词</td><td>长文生成时给 0.1 左右</td></tr></tbody></table><p>要「每次完全一致」，温度设 0 也做不到——批处理顺序、浮点误差都会带来微小差异。需要可复现时，把结果存下来，别指望重跑复现。</p><h3 id="参数规模与显存" tabindex="-1">参数规模与显存 <a class="header-anchor" href="#参数规模与显存" aria-label="Permalink to &quot;参数规模与显存&quot;">​</a></h3><p>粗算规则：<strong>每 10 亿参数约需 2GB 显存（FP16）</strong>，再加上 KV Cache 和上下文长度还要涨。</p><table tabindex="0"><thead><tr><th>模型规模</th><th>FP16 显存下限</th><th>4bit 量化后</th><th>现实结论</th></tr></thead><tbody><tr><td>7B</td><td>约 14GB</td><td>约 4–5GB</td><td>8GB 显卡能跑量化版</td></tr><tr><td>13B</td><td>约 26GB</td><td>约 8GB</td><td>16GB 显卡勉强</td></tr><tr><td>70B</td><td>约 140GB</td><td>约 40GB</td><td>消费级单卡基本没戏</td></tr></tbody></table><p>跑不动时，先换小模型或量化版本，再考虑换硬件。</p><h2 id="有什么用" tabindex="-1">有什么用 <a class="header-anchor" href="#有什么用" aria-label="Permalink to &quot;有什么用&quot;">​</a></h2><p>不碰这块的代价很具体：写文档逐条翻资料、读陌生仓库一行行猜、做表格手工搬运、重复解释同一个业务背景。更糟的是把模型当搜索引擎，拿到一段通顺答案直接进生产，出错时连错在哪都说不清。</p><p>反过来，它的价值集中在四类场景：</p><table tabindex="0"><thead><tr><th>场景</th><th>解决什么</th></tr></thead><tbody><tr><td>写文档、写周报、写公告</td><td>从零起稿变成改稿，时间花在判断而不是打字</td></tr><tr><td>读代码、读报错、读陌生仓库</td><td>先让它解释一遍，再自己去验证，缩短「看不懂」的时长</td></tr><tr><td>批量整理非结构化文本</td><td>转成表格字段，省掉逐条搬运</td></tr><tr><td>把对话能力接进产品</td><td>用 API 或 SDK 变成功能，而不是手动复制粘贴</td></tr></tbody></table>',24)])])}const _=d(o,[["render",h]]);export{c as __pageData,_ as default};
